package main

import "fmt"

func Max[T comparable](s []T) T {
	if len(s) == 0 {
		var zero T
		return zero
	}
	max := s[0]
	for _, v := range s {
		if v > max {
			max = v
		}
	}
	return max
}

func main() {
	fmt.Println(Max([]int{3, 7, 2, 9, 1}))
	fmt.Println(Max([]float64{2.5, 1.1, 4.8}))
}

